export default Employee;

const TaskCard = ({ subtask }) => {
  return (
    <div className="p-4 rounded-xl border border-gray-300 bg-white max-w-xs">
      <div className="-ml-0.5 mb-2">
        <TableSiteStatus title={subtask?.status} />
      </div>
      <h2 className="text-sm font-semibold text-neutral-800 whitespace-nowrap truncate">
        {subtask?.subtaskTitle}
      </h2>
      <div className="mt-3 flex justify-between items-center text-neutral-500">
        <div className="flex items-center gap-2">
          <ListTodo className="size-5" />
          <span className="text-sm">Progress</span>
        </div>
        <span className="text-sm">{subtask?.progress}%</span>
      </div>
      <Progress
        className="mt-4 h-1"
        indicatorColor={`
                                ${
                                  subtask?.progress === 100
                                    ? "bg-[#16a34a]"
                                    : subtask?.progress > 60
                                    ? "bg-rose-600"
                                    : "bg-[#2563eb]"
                                }
                                `}
        value={subtask?.progress}
      />
      <div className="mt-5 flex justify-between items-center text-neutral-500">
        <div className="flex items-center gap-1">
          <CalendarClock className="size-3" />
          <span className="text-xs tracking-tight whitespace-nowrap truncate">
            {new Date(subtask.startDate).toDateString()} -{" "}
            {new Date(subtask.endDate).toDateString()}
          </span>
        </div>
      </div>
    </div>
  );
};

const TaskTabel = ({ filteredData }) => {
  const [expandedEmployee, setExpandedEmployee] = useState();
  const [expandedTask, setExpandedTask] = useState();
  const toggleEmployeeExpansion = (employeeId) => {
    setExpandedEmployee((prev) => (prev === employeeId ? null : employeeId));
    setExpandedTask(null); // Close any open tasks when toggling employee
  };

  const toggleTaskExpansion = (taskId) => {
    setExpandedTask((prevId) => (prevId === taskId ? null : taskId));
  };

  //   if (!filteredData || filteredData.length === 0) {
  //     return <div className="p-4 text-center">No data available</div>;
  //   }
  return (
    <Table>
      <TableHeader>
        <TableRow>
          {[
            "id",
            "Task",
            "Name",
            "priority",
            "status",
            "tasks",
            "Subtasks",
          ].map((item, index) => (
            <TableHead className="uppercase text-xs" key={index}>
              {item}
            </TableHead>
          ))}
        </TableRow>
      </TableHeader>
      {!filteredData || filteredData.length === 0 ? (
        <div className="w-full flex items-center justify-center">
          <NotFoundData />
        </div>
      ) : (
        <TableBody>
          {filteredData.map((employee, employeeIndex) => (
            <Fragment key={employee.employeeId || employeeIndex}>
              <TableRow className="hover:bg-gray-50">
                <TableCell>{employeeIndex + 1}</TableCell>
                <TableCell>
                  <div className="font-medium">
                    {employee.employeeName || "N/A"}
                  </div>
                </TableCell>
                <TableCell className="font-medium">
                  <div className="flex items-center space-x-2">
                    <div
                      className="cursor-pointer"
                      onClick={() =>
                        toggleEmployeeExpansion(employee.employeeId)
                      }
                    >
                      {expandedEmployee === employee.employeeId ? (
                        <ChevronDown className="w-4 h-4 text-gray-500" />
                      ) : (
                        <ChevronRight className="w-4 h-4 text-gray-500" />
                      )}
                    </div>
                    <span>Tasks ({employee.tasks?.length || 0})</span>
                  </div>
                </TableCell>
                <TableCell>-</TableCell>
                <TableCell>-</TableCell>
                <TableCell>{employee.tasks?.length || 0}</TableCell>
                <TableCell>
                  {employee.tasks.reduce((acc, task) => {
                    return acc + task.subtasks.length;
                  }, 0)}
                </TableCell>
              </TableRow>
              {expandedEmployee === employee.employeeId &&
                employee.tasks &&
                employee.tasks.map((task, taskIndex) => (
                  <Fragment
                    key={task.id || `${employee.employeeId}-task-${taskIndex}`}
                  >
                    <TableRow className="hover:bg-gray-50">
                      <TableCell></TableCell>
                      <TableCell></TableCell>
                      <TableCell>
                        <div className="flex items-center space-x-2 ml-6">
                          <div
                            className="cursor-pointer"
                            onClick={
                              task.subtasks.length > 0
                                ? () => toggleTaskExpansion(task.id)
                                : undefined
                            }
                          >
                            {expandedTask === task.id ? (
                              task.subtasks.length > 0 ? (
                                <ChevronDown className="w-4 h-4 mr-2" />
                              ) : (
                                <CircleX className="w-4 h-4 mr-2 text-neutral-400" />
                              )
                            ) : task.subtasks.length > 0 ? (
                              <ChevronRight className="w-4 h-4 mr-2" />
                            ) : (
                              <CircleX className="w-4 h-4 mr-2 text-neutral-400" />
                            )}
                          </div>
                          <span className="font-medium">
                            {task.taskTitle || "Untitled Task"}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell>{task.taskPriority || "-"}</TableCell>
                      <TableCell>
                        <TableSiteStatus title={task.taskStatus} />
                      </TableCell>
                      <TableCell>-</TableCell>
                      <TableCell>{task.subtasks?.length || 0}</TableCell>
                    </TableRow>
                    {expandedTask === task.id && (
                      <TableRow>
                        <TableCell colSpan={7}>
                          <ul className="ps-7 relative mt-2 space-y-2 before:bg-neutral-400 before:w-0.5 before:h-full before:top-0 before:start-[18px] before:absolute">
                            <div className="grid md:grid-cols-3 sm:grid-cols-2 xl:lg:grid-cols-4 grid-cols-1 gap-2">
                              {task.subtasks.map((subtask, subtaskIndex) => (
                                <TaskCard
                                  key={subtaskIndex}
                                  subtask={subtask}
                                />
                              ))}
                            </div>
                            {task.subtasks.length === 0 && (
                              <div className="text-sm text-muted-foreground bg-neutral-200 py-1 px-2 rounded-md flex items-center">
                                <span className="mt-0.5"> No subtasks</span>
                              </div>
                            )}
                          </ul>
                        </TableCell>
                      </TableRow>
                    )}
                  </Fragment>
                ))}
            </Fragment>
          ))}
        </TableBody>
      )}
    </Table>
  );
};

